C++ code demonstrating RVO/NRVO:

```c++
class MyClass {
public:
  MyClass() { std::cout << "Constructor called\n"; }
  MyClass(const MyClass&) { std::cout << "Copy constructor called\n"; }
  ~MyClass() { std::cout << "Destructor called\n"; }
};

MyClass createMyClass() {
  MyClass obj;
  return obj; // RVO likely here
}

MyClass createMyClassNamed() {
  MyClass obj;
  return obj; // NRVO likely here
}

int main() {
  MyClass a = createMyClass();
  MyClass b = createMyClassNamed();
  return 0;
}
```
